const on=(id,fn)=>{if($(id))$(id).onclick=()=>run(fn)};on('#server-resend',async()=>{email=form.querySelector('[name=email]').value.trim();if(!form.reportValidity())return;const r=await call('/api/auth/'+(form.dataset.type==='recovery'?'recover':'resend'),{method:'POST',body:{email}});msg(r.message)});
